"""The SDK's own calls to Phoenix. Everything here fails soft: a heal that
cannot complete returns None and the caller serves the original response."""
from __future__ import annotations

import contextvars
import os
import threading
import queue
import logging
import anyio
import time
from dataclasses import dataclass
from typing import Any, Optional

import httpx

from .config import HEAL_TIMEOUT_SECONDS, Config
from .version import VERSION
from .gate import bounded_json

logger = logging.getLogger("mnfst")
_HEAL_SLOTS = threading.BoundedSemaphore(8)
MAX_HEAL_RESPONSE = 1_048_576
HELLO_TIMEOUT_SECONDS = 5.0
REQUESTS_TIMEOUT_SECONDS = 5.0

# Returned by HealApi.heal when every heal slot is busy: the failure was never
# sent, so the caller tracks it instead of losing it from both ledgers.
NOT_SENT = object()


def _bounded_call(call):
    if not _HEAL_SLOTS.acquire(blocking=False):
        return NOT_SENT
    result = queue.Queue(maxsize=1)
    def run():
        try:
            result.put(call())
        except Exception:
            result.put(None)
        finally:
            _HEAL_SLOTS.release()
    try:
        threading.Thread(target=run, daemon=True).start()
    except Exception:
        _HEAL_SLOTS.release()
        return None
    try:
        return result.get(timeout=HEAL_TIMEOUT_SECONDS)
    except queue.Empty:
        return None


internal_call = contextvars.ContextVar("mnfst_internal_call", default=False)

DISABLED_BACKOFF_SECONDS = 300
MAX_INFLIGHT_REPORTS = 64

# An attempt Phoenix opened that we never replayed (strip mode, or nothing
# replayable came back). Reported so the attempt ledger closes instead of
# holding open an answer that will never arrive.
NOT_ATTEMPTED = "replay_not_attempted"


@dataclass
class HealEvent:
    url: str
    status_code: int
    heal_status: str
    replay_status_code: Optional[int]
    heal_ms: int
    operations: Optional[list]


def _headers(config: Config) -> dict:
    headers = {
        "user-agent": f"mnfst-python/{VERSION}",
    }
    if config.api_key:
        headers["authorization"] = f"Bearer {config.api_key}"
    return headers


class _Disable:
    """Shared kill-switch backoff state."""

    def __init__(self) -> None:
        self._disabled_until = 0.0

    def enabled(self) -> bool:
        return time.monotonic() >= self._disabled_until

    def trip(self) -> None:
        self._disabled_until = time.monotonic() + DISABLED_BACKOFF_SECONDS


def _is_app_disabled(response: httpx.Response) -> bool:
    if response.status_code != 403:
        return False
    try:
        body = response.json()
        return isinstance(body, dict) and (body.get("error") == "project_disabled" or body.get("status") == "app_disabled")
    except ValueError:
        return False


class HealApi:
    def __init__(self, config: Config, transport: Optional[httpx.BaseTransport] = None):
        self._client = httpx.Client(base_url=config.base_url, timeout=HEAL_TIMEOUT_SECONDS,
                                    transport=transport, headers=_headers(config))
        self._disable = _Disable()
        self._pending: list[threading.Thread] = []
        self._pending_lock = threading.Lock()
        self.report_failures = 0
        self.reports_dropped = 0
        self._config = config
        self._transport = transport
        self._tracking_client: Optional[httpx.Client] = None
        self._tracking_pid: Optional[int] = None

    def _tracking(self) -> httpx.Client:
        """A client of this process's own for tracked-call sends. A forked
        worker must not reuse the parent's pool: its keep-alive socket would be
        shared across processes, and a lock held mid-request at fork time
        would never be released in the child."""
        pid = os.getpid()
        if self._tracking_client is None or self._tracking_pid != pid:
            self._tracking_client = httpx.Client(
                base_url=self._config.base_url, transport=self._transport,
                headers=_headers(self._config), timeout=REQUESTS_TIMEOUT_SECONDS)
            self._tracking_pid = pid
        return self._tracking_client

    @property
    def _disabled_until(self) -> float:
        return self._disable._disabled_until

    @_disabled_until.setter
    def _disabled_until(self, value: float) -> None:
        self._disable._disabled_until = value

    def healing_enabled(self) -> bool:
        return self._disable.enabled()

    def heal(self, payload: dict) -> Optional[dict]:
        return _bounded_call(lambda: self._heal(payload))

    def _heal(self, payload: dict) -> Optional[dict]:
        if not self._disable.enabled():
            return None
        token = internal_call.set(True)
        try:
            # The post() call stays inside the try: serializing a pathological
            # payload can raise, and that must fail open like any other error.
            if not bounded_json(payload):
                return None
            with self._client.stream("POST", "/v1/heal", json=payload) as streamed:
                data = bytearray()
                for chunk in streamed.iter_bytes():
                    if len(data) + len(chunk) > MAX_HEAL_RESPONSE:
                        return None
                    data.extend(chunk)
                response = httpx.Response(streamed.status_code, content=bytes(data))
            if _is_app_disabled(response):
                self._disable.trip()
                return None
            if response.status_code != 200:
                return None
            result = response.json()
            return result if isinstance(result, dict) else None
        except Exception:
            return None
        finally:
            internal_call.reset(token)

    def hello(self, runtime: str) -> None:
        """Announce this install: "I am installed."

        Without it a broken install and a healthy app look identical from the
        dashboard — both are silence. Four causes hide behind that silence (key
        unset, key invalid, app not restarted, SDK never loaded), and an app
        with no failing calls produces exactly the same nothing.

        Deliberately fire-and-forget and deliberately quiet. It carries no
        application data: the SDK name and version ride in the user-agent this
        client already sends, so the body is the runtime and nothing else. A
        failure is not warned about — the dashboard showing "not connected" IS
        the signal, and an app that cannot reach Manifest must not print on
        every boot.

        The internal_call guard keeps the handshake from being captured by our
        own patch, and it is never gated by the disabled backoff: reaching
        Manifest is the point.
        """
        def _send() -> None:
            token = internal_call.set(True)
            try:
                response = self._client.post("/v1/hello", json={"runtime": runtime},
                                             timeout=HELLO_TIMEOUT_SECONDS)
                response.close()
            except Exception:
                pass
            finally:
                internal_call.reset(token)

        try:
            threading.Thread(target=_send, daemon=True).start()
        except Exception:
            pass

    def send_requests(self, calls: list) -> None:
        """Ship one batch of tracked calls to `POST /v1/requests`.

        Raises only when a retry could help (network error, timeout, 429, 5xx)
        so the buffer retries once; any other answer, including 404 from a
        server that predates the route, drops the batch quietly. Runs on the
        tracking worker thread, under the internal_call guard, so the send is
        never tracked or healed by our own patch.
        """
        if not calls or not self._disable.enabled():
            return
        token = internal_call.set(True)
        try:
            response = self._tracking().post("/v1/requests", json={"requests": calls})
            try:
                if _is_app_disabled(response):
                    self._disable.trip()
                elif response.status_code == 429 or response.status_code >= 500:
                    raise RuntimeError(f"tracked calls refused ({response.status_code})")
            finally:
                response.close()
        finally:
            internal_call.reset(token)

    def report_outcome(self, heal_attempt_id: str, retry_status_code: int,
                       error: Any = None, truncated: bool = False) -> None:
        if retry_status_code == 0:
            body = {"failure": {"kind": "not_attempted" if error == NOT_ATTEMPTED else "transport_error", "message": error or NOT_ATTEMPTED}}
        else:
            body = {"response": {"statusCode": retry_status_code}}
            if error is not None:
                body["response"].update(body=error, truncated=truncated)

        def _send() -> None:
            internal_call.set(True)
            try:
                response = self._client.patch(f"/v1/heal-attempts/{heal_attempt_id}", json=body)
                response.raise_for_status()
            except Exception:
                with self._pending_lock:
                    self.report_failures += 1
                logger.warning("Outcome report failed; attempt remains unconfirmed")

        thread = threading.Thread(target=_send, daemon=True)
        with self._pending_lock:
            # Reports are fire-and-forget, so nothing else ever clears this in
            # a long-running process — sweep the finished ones as we go, and
            # under a flood drop the report rather than spawn without bound:
            # a lost outcome costs one learning signal, not the host process.
            self._pending = [t for t in self._pending if t.is_alive()]
            if len(self._pending) >= MAX_INFLIGHT_REPORTS:
                self.reports_dropped += 1
                logger.warning("Outcome report capacity reached; report dropped")
                return
            self._pending.append(thread)
            thread.start()


class AsyncHealApi:
    def __init__(self, config: Config, transport: Optional[httpx.AsyncBaseTransport] = None):
        self._client = httpx.AsyncClient(base_url=config.base_url, timeout=HEAL_TIMEOUT_SECONDS,
                                         transport=transport, headers=_headers(config))
        self._sync = HealApi(config)  # outcome reports go out on threads either way
        self._disable = self._sync._disable

    def healing_enabled(self) -> bool:
        return self._disable.enabled()

    async def heal(self, payload: dict) -> Optional[dict]:
        try:
            with anyio.fail_after(HEAL_TIMEOUT_SECONDS):
                return await self._heal(payload)
        except TimeoutError:
            return None

    async def _heal(self, payload: dict) -> Optional[dict]:
        if not self._disable.enabled():
            return None
        token = internal_call.set(True)
        try:
            # Same fail-open envelope as the sync client, serialization included.
            if not bounded_json(payload):
                return None
            async with self._client.stream("POST", "/v1/heal", json=payload) as streamed:
                data = bytearray()
                async for chunk in streamed.aiter_bytes():
                    if len(data) + len(chunk) > MAX_HEAL_RESPONSE:
                        return None
                    data.extend(chunk)
                response = httpx.Response(streamed.status_code, content=bytes(data))
            if _is_app_disabled(response):
                self._disable.trip()
                return None
            if response.status_code != 200:
                return None
            result = response.json()
            return result if isinstance(result, dict) else None
        except Exception:
            return None
        finally:
            internal_call.reset(token)

    def hello(self, runtime: str) -> None:
        self._sync.hello(runtime)

    def report_outcome(self, heal_attempt_id: str, retry_status_code: int,
                       error: Any = None, truncated: bool = False) -> None:
        self._sync.report_outcome(heal_attempt_id, retry_status_code, error, truncated)

from mnfst.merge import merge_healed_body


def test_full_travel_healed_wins_and_deletes_by_omission():
    original = {"model": "gpt-5", "temperature": 0.2, "messages": [1]}
    traveled = dict(original)
    healed = {"model": "gpt-5", "messages": [1]}  # temperature omitted -> dropped
    assert merge_healed_body(original, traveled, healed) == {"model": "gpt-5", "messages": [1]}


def test_never_traveled_keys_are_restored():
    original = {"secret": "s3cr3t", "reps": "10"}
    traveled = {"reps": "10"}          # strip mode kept 'secret' home
    healed = {"reps": 10}
    assert merge_healed_body(original, traveled, healed) == {"secret": "s3cr3t", "reps": 10}


def test_healed_can_add_new_keys():
    original = {"a": 1}
    assert merge_healed_body(original, {"a": 1}, {"a": 1, "b": 2}) == {"a": 1, "b": 2}


def test_empty_travel_restores_all_untouched_keys():
    assert merge_healed_body({"a": 1, "b": 2}, {}, {"b": 3}) == {"a": 1, "b": 3}


def test_healed_named_key_beats_restore():
    original = {"secret": "old", "a": 1}
    # server named 'secret' even though it didn't travel -> healed value wins
    assert merge_healed_body(original, {"a": 1}, {"a": 1, "secret": "new"}) == {"a": 1, "secret": "new"}


def test_non_object_bodies_are_replaced_wholesale():
    assert merge_healed_body(["a", "bad"], ["a", "bad"], ["a"]) == ["a"]
    assert merge_healed_body({"a": 1}, {"a": 1}, ["now", "a", "list"]) == ["now", "a", "list"]
    assert merge_healed_body("scalar", "scalar", {"obj": True}) == {"obj": True}

import pytest

from mnfst.gate import REQUEST_BODY_LIMIT, parse_json_body, should_capture


@pytest.mark.parametrize("status", [400, 404, 405, 409, 410, 413, 415, 422, 428, 451, 499])
def test_any_request_side_4xx_is_captured(status):
    assert should_capture(status)


@pytest.mark.parametrize("status", [200, 201, 204, 301, 302, 401, 402, 403, 429, 500, 502, 599])
def test_forbidden_and_non_failure_statuses_pass_through(status):
    # auth, billing, rate limits and server faults: editing the request
    # cannot fix any of them, so reporting them is noise
    assert not should_capture(status)


def test_any_json_body_travels():
    assert parse_json_body(b'{"reps": "10"}') == {"reps": "10"}
    assert parse_json_body(b"[1,2]") == [1, 2]  # arrays: bulk endpoints
    assert parse_json_body(b'"just a string"') == "just a string"
    assert parse_json_body(b"not json") is None
    assert parse_json_body(None) is None
    assert parse_json_body(b"") is None


def test_body_size_limit():
    big = b'{"k": "' + b"x" * REQUEST_BODY_LIMIT + b'"}'
    assert parse_json_body(big) is None


def test_hostile_depth_fails_open():
    deep = b"[" * 20000 + b"]" * 20000
    assert parse_json_body(deep) is None  # RecursionError swallowed

from importlib import metadata, resources

import pytest

from mnfst import VERSION


def test_runtime_version_matches_distribution_metadata():
    try:
        distribution_version = metadata.version("mnfst")
    except metadata.PackageNotFoundError:
        pytest.skip("distribution metadata requires an installed package")
    assert VERSION == distribution_version


def test_typing_marker_is_packaged():
    assert resources.files("mnfst").joinpath("py.typed").is_file()


def test_bootstrap_is_packaged():
    assert resources.files("mnfst").joinpath("_bootstrap", "sitecustomize.py").is_file()


def test_console_script_is_declared():
    try:
        distribution = metadata.distribution("mnfst")
    except metadata.PackageNotFoundError:
        pytest.skip("distribution metadata requires an installed package")
    scripts = {ep.name: ep.value for ep in distribution.entry_points
               if ep.group == "console_scripts"}
    assert scripts.get("mnfst") == "mnfst.__main__:main"

import time


def wait_for(predicate, timeout=3.0):
    """Poll predicate until true or timeout. Test-only: outcome reports are
    fire-and-forget, so tests observe the result instead of draining them."""
    deadline = time.time() + timeout
    while time.time() < deadline:
        if predicate():
            return True
        time.sleep(0.02)
    return False
